contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(address _recipient) external {
        // The test contract is not the owner, so P must reject its withdrawal.
        require(c.owner() != address(this));

        // Fund c through its payable fallback.
        (bool ok, ) = address(c).call{value: 1 wei}("");
        require(ok);

        // Deciding call: a non-owner attempts to drain the funds.
        c.withdrawAll(_recipient);

        // On P this call reverts (so the test holds vacuously);
        // on M the attacker drains c, leaving zero balance and violating the rule.
        assert(address(c).balance > 0);
    }
}

