contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address _recipient) external {
        // Only meaningful if the test contract is the owner so withdrawAll can run.
        require(c.owner() == address(this));
        require(address(this).balance >= 1 ether);

        // Fund c via its payable fallback (top-level statement).
        (bool okFund, ) = address(c).call{value: 1 ether}("");
        assert(okFund);

        // On P, funds go to _recipient and this succeeds; c's balance becomes 0.
        // On M, funds go to msg.sender (this contract, which has no receive), so
        // the transfer reverts and the final assert is never reached -> violated.
        c.withdrawAll(_recipient);

        assert(address(c).balance == 0);
    }
}

