contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }
        // Rule: the call reverts iff the caller (this test contract) is not the owner.
        // If this contract IS the owner, P still reverts because the recipient
        // (this contract, which has no receive/fallback) cannot accept ETH,
        // since P always pays _recipient. M pays the owner instead and succeeds,
        // breaking the rule in that case.
        assert(reverted == (c.owner() != address(this)));
    }
}

