contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address _recipient) public payable {
        // Only input preconditions
        require(c.owner() == address(this));
        require(_recipient != address(this));
        // Fund c with a top-level call (fallback is payable)
        if (amount > 0) {
            require(address(this).balance >= amount);
            address(c).call{value: amount}("");
        }
        require(address(c).balance > 0);
        bool reverted;
        try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
        // P (owner calls): whole balance goes to _recipient; call succeeds and c is drained.
        // M pays msg.sender instead, which cannot accept ETH, so M reverts and c keeps funds.
        assert(!reverted && address(c).balance == 0);
    }
}

